// Curated how-to guides for the triage "safety steps".
//
// These are written by hand, not generated by the AI, because safety advice
// should be reviewed. The AI only picks which safety steps apply. This file
// explains how to do each one, so a tenant does not have to search the web.
//
// General safety information only. It is not a substitute for a professional.
// See README, "Before real use": have a licensed plumber and your gas utility
// review these before real tenants rely on them.

export interface SafetyGuide {
  id: string;
  title: string;
  time: string;
  youNeed: string;
  why: string;
  steps: string[];
  stopIf: string[];
  /** Which small diagram to show, if any */
  diagram?: "valve";
  /** A line pulled from the house record, when we know something useful */
  recordNote?: string;
}

/** What we know about the equipment from the house record. All optional. */
export interface HouseContext {
  manufacturer?: string | null;
  model?: string | null;
  fuelType?: string | null;
}

interface GuideEntry {
  test: RegExp;
  build: (ctx: HouseContext) => SafetyGuide;
}

function heaterName(ctx: HouseContext): string | null {
  const parts = [ctx.manufacturer, ctx.model].filter(Boolean);
  return parts.length ? parts.join(" ") : null;
}

function isElectric(ctx: HouseContext): boolean {
  return /electric/i.test(ctx.fuelType ?? "");
}

