/** The guide for one safety step, or null if we have nothing to add for it. */
export function guideForStep(step: string, ctx: HouseContext = {}): SafetyGuide | null {
  const entry = ENTRIES.find((e) => e.test.test(step));
  return entry ? entry.build(ctx) : null;
}
